    // instead of jumping straight into Options, mirroring the in-game Esc GAME MENU.
    bool settingsMenu_ = false;
    // By id: GRAPHICS / CONTROLS / VOICE CHAT / BENCHMARK / LOAD REPLAY / STREAMING / AUDIO /
    // USER INTERFACE / GAME, shown in kSettingsOrder: GAME, GRAPHICS, USER INTERFACE, AUDIO,
    // VOICE CHAT, CONTROLS, BENCHMARK, LOAD REPLAY, YOUTUBE STREAMING.
    SDL_FRect setBtnRect_[9]{};
    static constexpr int kSettingsOrder[9] = {8, 0, 7, 6, 2, 1, 3, 4, 5};
    SDL_FRect menuBackRect_{};         // the BACK button of SETTINGS, BENCHMARK and LOAD REPLAY (set each render)
    VoiceEngine* voice_ = nullptr;     // main()'s voice engine (MainMenu::setVoice)

    // The VOICE CHAT page (SETTINGS > VOICE CHAT, or Options > VOICE CHAT), in options_.
    void openVoicePage(Settings* settings) {
        VoicePageHooks hooks;
        if (VoiceEngine* v = voice_) {
            hooks.micLevel = [v] { return v->micLevel(); };
            hooks.micNote = [v] { return VoiceEngine::note(v->micState()); };
            hooks.outNote = [v] { return VoiceEngine::note(v->outState()); };
            hooks.monitor = [v](bool on) { v->setMonitoring(on); };
        }
        // The engine reads the settings every frame (run()); each change is saved as made.
        options_ = std::make_unique<OptionsScreen>(ren, *settings, [] {},
            [settings] { saveSettings(*settings); }, std::move(hooks),
            [this, settings] {   // PUSH TO TALK -> CONTROLS, over this page
                hotkeys_ = std::make_unique<HotkeysScreen>(ren, *settings,
                    [] {}, [settings] { saveSettings(*settings); });
            });
    }
    bool benchMenu_ = false;          // benchmark intensity submenu (opened from SETTINGS)
    bool replayMenu_ = false;         // replay picker (opened from SETTINGS)
    int replayScroll_ = 0;            // first listed row
    static constexpr int kReplayRows = 10;   // rows on show at once
    SDL_FRect replayTrack_{}, replayThumb_{};   // the scroll bar (empty while it all fits)
    bool replayDrag_ = false;                   // the thumb is held
    float replayDragOff_ = 0;                   // where on the thumb it was taken
    int replayMaxTop() const { return std::max(0, int(replayFiles_.size()) - kReplayRows); }
    // The list scrolled so the thumb's top sits at y (the thumb dragged there).
    void replayScrollTo(float thumbTop) {
        const float room = replayTrack_.h - replayThumb_.h;
        const float t = room > 0 ? std::clamp((thumbTop - replayTrack_.y) / room, 0.0f, 1.0f) : 0.0f;
        replayScroll_ = int(std::lround(t * float(replayMaxTop())));
    }
    std::vector<std::string> replayFiles_;   // full paths, newest first: the ones this build can play
    std::vector<std::string> replayLength_;  // each one's game length ("" when its header does not say)
    size_t replayOthers_ = 0;                // .tarep files of other versions, not listed
    std::string chosenReplay_;
    std::string replayError_;         // shown on the picker
    SDL_FRect replayBtnRect_[kReplayRows]{};   // one per listed row (set each render)
    SDL_FRect benchBtnRect_[6]{};      // LOW..EXTRA ABSURD hit-rects (set each render)
    SDL_FRect benchPathRect_[2]{};     // its PATHFINDING choices, kBenchmarkPaths order (set each render)
    SDL_FRect benchSpeedRect_[3]{};    // its SPEED choices, kBenchmarkSpeeds order (set each render)
    int chosenBenchmark_ = 0;         // picked benchmark level 1..6 (0 = none)

